#include <stdio.h>
#include <string.h>
int main(void){
    const char *txt="hello", *pat="ell";
    int n=(int)strlen(txt), m=(int)strlen(pat);
    int base=100;                 /* 每位 1..26，base=100 保证无进位串味 */
    long power=1; for(int i=1;i<m;i++) power*=base;   /* base^(m-1) */
    long ph=0;
    for(int i=0;i<m;i++) ph = ph*base + (pat[i]-'a'+1);
    long hw=0;
    for(int i=0;i<m;i++) hw = hw*base + (txt[i]-'a'+1);
    printf("文本: %s  模式: %s  (base=%d)\n", txt, pat, base);
    printf("窗口哈希:\n");
    int matched=0;
    printf("  [0] %.*s -> %ld%s\n", m, txt, hw, (hw==ph?"  <- 匹配":""));
    if(hw==ph){ printf("  匹配起始位置(0基): 0\n"); matched=1; }
    for(int s=1;s+m<=n;s++){
        hw = (hw - (txt[s-1]-'a'+1)*power)*base + (txt[s+m-1]-'a'+1);
        printf("  [%d] %.*s -> %ld%s\n", s, m, txt+s, hw, (hw==ph?"  <- 匹配":""));
        if(hw==ph){ printf("  匹配起始位置(0基): %d\n", s); matched=1; }
    }
    if(!matched) printf("未找到匹配\n");
    return 0;
}
